namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public int InstructorId { get; set; }
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "The science of numbers, quantities, and shapes." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Literature, writing, and language studies." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Exploration of past events and civilizations." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in distributed systems and has published over 50 papers in top-tier conferences. She received her PhD from MIT and has 15 years of teaching experience.", Email = "achen@university.edu" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor of Mathematics", Bio = "Dr. Martinez focuses on applied mathematics and numerical analysis. He is the author of two widely-used textbooks on linear algebra.", Email = "rmartinez@university.edu" },
            new() { Id = 3, Name = "Prof. Sarah Williams", Title = "Professor of English", Bio = "Prof. Williams is an award-winning author and literary critic specializing in 20th-century American literature.", Email = "swilliams@university.edu" },
            new() { Id = 4, Name = "Dr. James Park", Title = "Professor of Physics", Bio = "Dr. Park's research in quantum mechanics has been cited over 3,000 times. He leads the university's Quantum Computing Lab.", Email = "jpark@university.edu" },
            new() { Id = 5, Name = "Dr. Emily Thompson", Title = "Associate Professor of History", Bio = "Dr. Thompson is a historian of early modern Europe with a focus on the social history of science and medicine.", Email = "ethompson@university.edu" },
            new() { Id = 6, Name = "Dr. Michael Rivera", Title = "Assistant Professor of Computer Science", Bio = "Dr. Rivera researches machine learning and computer vision. He previously worked at a major tech company for 8 years before joining academia.", Email = "mrivera@university.edu" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control structures, functions, and basic data structures. No prior programming experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 2, Code = "CS 301", Title = "Data Structures & Algorithms", Description = "Advanced study of data organization and algorithm design. Covers trees, graphs, hashing, sorting, and complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", DepartmentId = 1, InstructorId = 6, IsFeatured = true },
            new() { Id = 3, Code = "CS 450", Title = "Machine Learning", Description = "Introduction to machine learning techniques including supervised and unsupervised learning, neural networks, and deep learning fundamentals.", Credits = 3, Schedule = "Mon/Wed 2:00–3:30 PM", DepartmentId = 1, InstructorId = 6, IsFeatured = false },
            new() { Id = 4, Code = "MATH 201", Title = "Linear Algebra", Description = "Study of vectors, matrices, linear transformations, eigenvalues, and applications to computer science and engineering.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, InstructorId = 2, IsFeatured = true },
            new() { Id = 5, Code = "MATH 301", Title = "Differential Equations", Description = "First and second order differential equations, Laplace transforms, systems of equations, and numerical methods.", Credits = 4, Schedule = "Tue/Thu 1:00–2:30 PM", DepartmentId = 2, InstructorId = 2, IsFeatured = false },
            new() { Id = 6, Code = "ENG 101", Title = "Composition & Rhetoric", Description = "Develop critical reading and writing skills. Focus on argument construction, research methods, and clear prose.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentId = 3, InstructorId = 3, IsFeatured = false },
            new() { Id = 7, Code = "ENG 350", Title = "American Literature", Description = "Survey of major works in American literature from the colonial period to the present, with emphasis on cultural and historical context.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", DepartmentId = 3, InstructorId = 3, IsFeatured = true },
            new() { Id = 8, Code = "PHYS 201", Title = "Classical Mechanics", Description = "Newton's laws, energy, momentum, rotational dynamics, oscillations, and gravitation with calculus-based problem solving.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 4, InstructorId = 4, IsFeatured = false },
            new() { Id = 9, Code = "PHYS 401", Title = "Quantum Mechanics", Description = "Wave-particle duality, Schrödinger equation, quantum states, operators, and applications to atomic and molecular systems.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", DepartmentId = 4, InstructorId = 4, IsFeatured = true },
            new() { Id = 10, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations and events from prehistory through the late medieval period.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 5, InstructorId = 5, IsFeatured = false },
            new() { Id = 11, Code = "HIST 320", Title = "History of Science", Description = "Traces the development of scientific thought from ancient Greece to the modern era, exploring how science shaped and was shaped by society.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", DepartmentId = 5, InstructorId = 5, IsFeatured = true },
        };
    }

    public List<Department> GetAllDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> SearchCourses(string? query, int? departmentId)
    {
        var results = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            results = results.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(query))
        {
            var q = query.Trim().ToLowerInvariant();
            results = results.Where(c =>
                c.Title.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(q, StringComparison.OrdinalIgnoreCase));
        }

        return results.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public Department? GetDepartmentForCourse(int courseId)
    {
        var course = GetCourse(courseId);
        return course is null ? null : GetDepartment(course.DepartmentId);
    }
}

