arguments.file_text:
@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Courses — University Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="/courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <label for="query" class="form-label">Search</label>
        <input type="text" id="query" name="query" class="form-control" placeholder="Search by title, code, or keyword…" value="@Query" />
    </div>
    <div class="col-md-4">
        <label for="departmentId" class="form-label">Department</label>
        <select id="departmentId" name="departmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Schedule</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                var dept = Catalog.GetDepartmentForCourse(course.Id);
                <tr>
                    <td>@course.Code</td>
                    <td>@course.Title</td>
                    <td>@dept?.Name</td>
                    <td>@course.Credits</td>
                    <td>@course.Schedule</td>
                    <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery] public string? Query { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private List<Course> courses = new();
    private List<Department> departments = new();

    protected override void OnInitialized()
    {
        departments = Catalog.GetAllDepartments();
        courses = Catalog.SearchCourses(Query, DepartmentId);
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course does not exist.</p>
    <a href="/courses" class="btn btn-secondary">Back to Courses</a>
}
else
{
    <PageTitle>@course.Code — @course.Title</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/courses">Courses</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <h1>@course.Code — @course.Title</h1>

    <div class="row mt-4">
        <div class="col-md-8">
            <h2>Description</h2>
            <p>@course.Description</p>

            <h2 class="mt-4">Schedule</h2>
            <p><strong>@course.Schedule</strong></p>

            <h2 class="mt-4">Credits</h2>
            <p><span class="badge bg-primary fs-6">@course.Credits credits</span></p>
        </div>

        <div class="col-md-4">
            @if (department is not null)
            {
                <div class="card mb-3">
                    <div class="card-header">Department</div>
                    <div class="card-body">
                        <h5 class="card-title">@department.Name (@department.Code)</h5>
                        <p class="card-text">@department.Description</p>
                        <a href="/courses?departmentId=@department.Id" class="btn btn-outline-secondary btn-sm">View All @department.Code Courses</a>
                    </div>
                </div>
            }

            @if (instructor is not null)
            {
                <div class="card">
                    <div class="card-header">Instructor</div>
                    <div class="card-body">
                        <h5 class="card-title">@instructor.Name</h5>
                        <p class="text-muted">@instructor.Title</p>
                        <p class="card-text">@instructor.Bio</p>
                        <p class="card-text"><small class="text-muted">@instructor.Email</small></p>
                    </div>
                </div>
            }
        </div>
